import math

def count_rectangles_dodecagon():
    n = 12  # number of vertices
    directions = list(range(1, n//2 + 1))  # k from 1 to 6
    rectangles = 0

    # Function to check if two directions are perpendicular
    def are_perpendicular(k1, k2, n):
        # Perpendicular if their difference is 3 or 9 mod 12 (i.e. 90° apart)
        diff = abs(k1 - k2)
        return diff == n // 4 or diff == n - (n // 4)

    # For each unordered pair of directions
    for i in range(len(directions)):
        for j in range(i+1, len(directions)):
            k1, k2 = directions[i], directions[j]
            if are_perpendicular(k1, k2, n):
                # n//2 pairs of parallel lines in each direction
                rectangles += (n // 2) ** 2

    print(f"Number of rectangles in regular dodecagon: {rectangles}")

count_rectangles_dodecagon()
